-- M9.3 lessons after DONE; EKB-first, append-only/idempotent by code. No domain mutation.
DO $m93ekb$
DECLARE n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('IG_M9_3_EKB_LESSONS_20261011'));
 SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo='IG-M9-4-GOVERNED-COHORTS-001';
 IF n<>1 THEN RAISE EXCEPTION 'M93_EKB_PREEXISTING_AUTHORITY_COUNT_INVALID:%',n; END IF;
 IF EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo IN ('IG-M9-3-OBSERVATION-TERMINAL-CONFLATION-001','IG-M9-3-TEQUIV-STATIC-CORPUS-001','IG-M9-3-TEQUIV-CASE-COLLISION-001','IG-M9-3-RECEIPT-MANIFEST-BINDING-001','IG-M9-3-FINGERPRINT-WHOLE-DB-TIMEOUT-001','IG-M9-3-SHADOW-RECEIPT-AUTHORITY-SPLIT-001','IG-M9-3-TERMINAL-IMMUTABILITY-ROLLBACK-PROOF-001','IG-M9-3-DESIGN-SQL-ERROR-HIDDEN-001') GROUP BY codigo HAVING count(*)>1)
 THEN RAISE EXCEPTION 'M93_EKB_DUPLICATE_EXISTING_CODE'; END IF;
 UPDATE public.lf_error_knowledge
 SET descripcion=concat_ws(E'\n',nullif(descripcion,''),'[M9.3_20261011_AJUSTE_DINAMICO] M9.3 reintrodujo siete tipos fijos en runner/workflow/verificador pese a decisión M9.4 de selección por datos. PR #2181 sustituyó conjunto y cardinalidad por ALL_ACTIVE/SCREEN/TYPE; Github Actions 38025666374 consultó vista M9.4 y ejecutó solo pantalla AUTH-51. NUNCA exigir los siete en una prueba por pantalla; el 7/7 de M9.4 es la cobertura histórica vigente, no cardinalidad universal.'),
     prevencion=concat_ws(E'\n',nullif(prevencion,''),'M9.3 prevención transversal: el conjunto requerido y su alcance provienen de v_input_governance_representative_cohort_v1 y de la intención SCREEN/TYPE/ALL_ACTIVE; todo contrato y verificador aguas abajo deben conservarlos.'),
     validacion=concat_ws(E'\n',nullif(validacion,''),'M9.3 PASS: prueba real GH 38025666374 ejecutó solamente AUTH-51; contrato Git=ledger=DB 20261010034500; 5/5 checkpoints DONE, 0 bloqueos. No inferir PASS para DESIGN o cobertura global de esta prueba individual.'),
     evidencia=concat_ws(E'\n',nullif(evidencia,''),'M9.3 PR #2181 merged; AUTH-51 selected dynamically GH 38025666374; EKB recurrence recorded 2026-10-11.'),
     ultima_vez=now(),updated_at=now(),frecuencia=coalesce(frecuencia,0)+1
 WHERE codigo='IG-M9-4-GOVERNED-COHORTS-001'
   AND position('[M9.3_20261011_AJUSTE_DINAMICO]' in coalesce(descripcion,''))=0;
 INSERT INTO public.lf_error_knowledge
 (id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,
  primera_vez,ultima_vez,lote_origen,pr,estado,evidencia,created_at,updated_at,lifecycle_phase,
  consumer_role,root_cause_family,detectability,source_context,source_ref)
 SELECT gen_random_uuid(),v.codigo,'INPUT_GOVERNANCE',v.titulo,v.descripcion,v.causa_raiz,
        v.patron,v.prevencion,v.validacion,v.severidad,1,
        now(),now(),'IG_M9_3',v.pr,v.estado,v.evidencia,now(),now(),'EXECUTION',
        ARRAY['IG','ENGINEERING_AGENT']::text[],v.root_cause_family,'PROCESS_DEPENDENT',
        'IG_CURATOR_VALIDATOR_REFACTOR_V2 M9.3 / PAULO-090 / cierre 2026-10-10',v.source_ref
 FROM (VALUES ('IG-M9-3-OBSERVATION-TERMINAL-CONFLATION-001','Una prueba de pantalla PASABA, pero el cierre fallaba por exigir siete categorías fijas','El runner M9.3 aplicaba la condición de aceptación del barrido global al resultado de un caso individual. AUTH tuvo Core/Semantics/Curator/Validator PASS y T-EQUIV D0; aun así la corrida marcaba FAILURE hasta integrar la admisión por alcance.','Se mezclaron dos niveles de decisión: observación técnica de una pantalla y cierre de todas las membresías seleccionadas por autoridad de datos.','Las métricas de éxito de ejecución individual no deben usar la cardinalidad fija de la regresión global.','Separar COHORT_OBSERVED de terminal DONE. Pantalla: exigir solo su selección viva. Cobertura global: exigir exactamente las membresías gobernadas actualmente, no siete códigos embebidos. D4 tipado es HOLD, nunca aprobación; fingerprints sin escrituras.','PASS positivo: GitHub Actions 38025666374 ejecutó solo AUTH-51 y el verificador independiente validó PASS y cero fallos. Negativo: selección incompleta no puede acreditar la cobertura global.','HIGH','R5_EROSION_PROCESO','ACTIVO','2176,2181','PRs #2176/#2181; GH 38025666374; checkpoint FULL_PIPELINE_CANDIDATE DONE, 5/5 DONE final','github://cristhianlujan/claude-persona-lf-patch/actions/runs/38025666374'),
('IG-M9-3-TEQUIV-STATIC-CORPUS-001','El normalizador transversal reimponía tres pantallas fijas a T-EQUIV','Aunque M9.4 resolvía ejemplos desde Supabase, TEQUIV_CONSUMPTION recompilaba corpus_screen_ids=[1,43,58] y screen_count=3 mediante fn_engineering_action_spec_sanitize_v1.','La sanitización compartida sobreescribía la política dinámica del consumidor posterior al adaptador.','Un adapter genérico puede reintroducir literales que otra unidad ya retiró.','Permitir opt-in selection_mode=GOVERNED_DYNAMIC en el consumidor; conservar exactamente el comportamiento previo de consumidores sin opt-in. Verificar salida sin IDs literales y shadow con autoridad viva.','PR #2182, migración 20261010041000 Git=ledger=DB. Readback: corpus_screen_ids=null, screen_count fijo=null, shadow_contract ENGINEERING_T_EQUIV_DYNAMIC_CORPUS_V2, selected screen 51; suite PASSED y receipt VERIFIED.','HIGH','R5_EROSION_PROCESO','ACTIVO','2182','SQL BEGIN/ROLLBACK PASS; migration 20261010041000; T-EQUIV cp3 DONE; suite 8086d623-4f3f-4443-900a-a199e3df4df2','supabase://supabase_migrations.schema_migrations/20261010041000'),
('IG-M9-3-TEQUIV-CASE-COLLISION-001','T-EQUIV M9.3 reutilizaba un test_code perteneciente a M4.10','ENGINEERING_T_EQUIV_SHADOW_CORPUS existía en INPUT_GOVERNANCE_REGRESSION para M4.10; M9.3 no tenía caso canónico propio. Así no podía acreditarse correctamente el recibo por checkpoint/owner.','La identidad global (suite_code,test_code) fue reutilizada fuera de su unidad mientras el persistidor exige pertenencia local exacta.','Tests de capacidades compartidas requieren test_code estable por plan/unidad/checkpoint, no identidad de otro consumidor.','Generar código único por plan/unidad bajo opt-in, registrar el caso gobernado con expected_output acorde al contrato actual y verificar ownership local antes de acreditar PASS.','PR #2183, migración 20261010042500 Git=ledger=DB. Caso ENGINEERING_T_EQUIV_DYNAMIC_IG_CURATOR_VALIDATOR_REFACTOR_V2_M9_3; bundle PASSED/VERIFIED, checkpoint DONE.','HIGH','R5_EROSION_PROCESO','ACTIVO','2183','Migración #2183, readback case; suite 8086d623-4f3f-4443-900a-a199e3df4df2','supabase://public.lf_test_suite_runs/8086d623-4f3f-4443-900a-a199e3df4df2'),
('IG-M9-3-RECEIPT-MANIFEST-BINDING-001','La suite de T-EQUIV pasó pero recibo quedó INCOMPLETE por falta de binding_execution_id','Primera prueba reversible fn_engineering_run_test_persist_v1 emitió ENGINEERING_RUN_TEST_PASS_RECEIPT_BUNDLE_NOT_VERIFIED: suite PASSED, binding=null, dispatch ausente. El manifiesto no incluía binding_execution_id.','Se confundió execution_id del suite con el atributo explícito de enlace al binding del capability actual.','PASS de tests locales no demuestra la procedencia ni cierre del recibo transversal.','Para CAPABILITY_BOUND_EXECUTION exigir manifest.binding_execution_id, binding BOUND, dispatch y ejecuciones consumidor/orquestador COMPLETED; rechazo si cualquier recibo falta.','Negativa: sin binding_execution_id, transacción ROLLBACK y paquete INCOMPLETE. Positiva: con ID del binding fresco, paquete VERIFIED y transición T-EQUIV al 55% con readback.','HIGH','R2_NO_VE','ACTIVO','2182,2183','fn_engineering_run_test_persist_v1 trial INCOMPLETE; test suite 8086d623-4f3f-4443-900a-a199e3df4df2 PASSED/VERIFIED','supabase://public.lf_test_suite_runs/8086d623-4f3f-4443-900a-a199e3df4df2'),
('IG-M9-3-FINGERPRINT-WHOLE-DB-TIMEOUT-001','Fingerprint de tablas completas provocó timeout en lugar de un diagnóstico útil','Un trabajo de AUTH superó ~210 segundos en el snapshot posterior y salió FAILED aun con cuatro etapas correctas; el hashing completo de tablas no medía mejor la transacción de esa pantalla.','El fingerprint se calculaba fuera del alcance de casos seleccionados, mezclando coste ajeno con una comprobación de cero persistencia.','La verificación de no escritura debe cubrir su autoridad y las tres tablas declaradas sin escanear pantallas ajenas.','Pre/post hash delimitado por pantalla(s) seleccionadas, ids de runs/assessments/gap_proposals y ROLLBACK transaccional; verificar readback externo; no degradar prueba de 0 escrituras.','PR #2181; GH 38025666374 job AUTH-51 SUCCESS; comparador readback idéntico. Prueba negativa 3 fingerprints coincidentes en sandbox.','MEDIUM','R5_EROSION_PROCESO','ACTIVO','2181,2184','Antes: GH 38017898899 AUTH timeout; después GH 38025666374 SUCCESS y PR #2184','github://cristhianlujan/claude-persona-lf-patch/actions/runs/38025666374'),
('IG-M9-3-SHADOW-RECEIPT-AUTHORITY-SPLIT-001','Readback consultaba provenance_receipts pero el recibo tipado de M9.7 vive en ledger privado','SHADOW_READBACK leía conteos generales programacion.provenance_receipts. M9.7 ancló su recibo en private.lf_evidence_ledger_v1 y el gate específico verificó fuentes 187/1068. El bundle MISMATCH es distinto a equivalencia funcional D0.','Los contratos de productor/consumidor apuntaban a almacenes de recibos distintos y confundían comparación de manifiestos con equivalencia de pipeline.','Una prueba de presencia de recibo no se satisface por contar receipt_kind; ni un hash MISMATCH del bundle implica falla del pipeline.','Usar fn_input_governance_shadow_receipt_gate_v1 para el recibo tipado, comprobar ID/hash/origen y negativo missing snapshot. Separar comparación BUNDLE_DIGEST_ONLY de T-EQUIV D0 funcional de M9.3.','Gate M9.7 PASS SHADOW_BUNDLE_REPLAY_IDENTICAL (comparison result MISMATCH, functional_pipeline_equivalence_proven=false); snapshot inválido BLOCKED. M9.3 prueba D0 independiente y suite VERIFIED; SHADOW_READBACK DONE.','HIGH','R2_NO_VE','ACTIVO','2181,2182,2183','ledger receipt 0a091836-f8db-4063-965d-a02fa2fbd6d5; evidence #187 + #1068; gate positive and negative; M9.3 DONE','supabase://private.lf_evidence_ledger_v1/0a091836-f8db-4063-965d-a02fa2fbd6d5'),
('IG-M9-3-TERMINAL-IMMUTABILITY-ROLLBACK-PROOF-001','Hallazgo positivo: la base rechaza mutaciones a corridas terminales y conserva 3 tablas','Intento controlado UPDATE en input_readiness_runs de pantalla gobernada 51 devolvió SQLSTATE P0001 TERMINAL_INPUT_READINESS_RUN_IMMUTABLE; fingerprints de runs/assessments/gap_proposals iguales antes y después y tras ROLLBACK.','Control de inmutabilidad del dominio existente opera correctamente; el test negativo previo no lo acreditaba como evidencia explícita.','Una validación adversarial debe poder demostrar el bloqueo auténtico sin desactivar el guard ni insertar filas de candidato.','Probar intento de escritura terminal en sandbox y exigir rechazo exacto P0001, ROLLBACK, cero IDs de candidato y hashes externos iguales de las tres tablas. Una simulación/self-test no sustituye SQL real.','PR #2184; self-test 8 negativos; verificación SQL real PASS evidence_sha256=265d1b301e94430e0bfe4d829845de03eb3fd752788d12c90f09e59c4b627e74; checkpoint ZERO_AUTH_WRITES_NEGATIVE DONE.','MEDIUM','R4_NO_CUESTIONA','ACTIVO','2184','Guard P0001 TERMINAL_INPUT_READINESS_RUN_IMMUTABLE; prueba SQL sandbox ROLLBACK, 3 fingerprints y readback externo; PR #2184','github://cristhianlujan/claude-persona-lf-patch/pull/2184'),
('IG-M9-3-DESIGN-SQL-ERROR-HIDDEN-001','Hallazgo pendiente: fallo de SQL en DESIGN se resumía sin SQLSTATE ni error exacto','Corrida global previa 38017898899: DESIGN devolvió SQL_TRANSACTION_FAILED_EXIT_3. El ejecutor propagó BLOCKED a cuatro etapas sin exponer diagnóstico SQL específico; en esta conversación no se aisló ni corrigió esa causa. M9.3 se cerró con evidencia específica de pantalla 51, no con regresión global de DESIGN.','Falta observabilidad del error interno de la transacción reversible; la falla global no permite distinguir causa SQL de semántica/contrato.','Un fallo de un caso no debe multiplicarse artificialmente en todos los stages ni confundirse con fallo global del motor.','Conservar SQLSTATE y mensaje sanitizado por etapa, distinguir bloqueos propagados; probar DESIGN por selección dinámica SCREEN/TYPE y ejecutar regresión negativa de error SQL. No declarar DESIGN PASS hasta evidencia nueva.','HIGH','UNCLASSIFIED_WITH_REASON','ACTIVO','2181','Corrida 38017898899 DESIGN SQL_TRANSACTION_FAILED_EXIT_3; aún sin prueba correctiva específica; NO inventar resolución','github://cristhianlujan/claude-persona-lf-patch/actions/runs/38017898899','undefined')) AS v(codigo,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,root_cause_family,estado,pr,evidencia,source_ref)
 WHERE NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge old WHERE old.codigo=v.codigo);
 IF (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo IN ('IG-M9-3-OBSERVATION-TERMINAL-CONFLATION-001','IG-M9-3-TEQUIV-STATIC-CORPUS-001','IG-M9-3-TEQUIV-CASE-COLLISION-001','IG-M9-3-RECEIPT-MANIFEST-BINDING-001','IG-M9-3-FINGERPRINT-WHOLE-DB-TIMEOUT-001','IG-M9-3-SHADOW-RECEIPT-AUTHORITY-SPLIT-001','IG-M9-3-TERMINAL-IMMUTABILITY-ROLLBACK-PROOF-001','IG-M9-3-DESIGN-SQL-ERROR-HIDDEN-001'))<>8
 THEN RAISE EXCEPTION 'M93_EKB_MISSING_NEW_ROWS'; END IF;
END $m93ekb$;
